<?php require_once 'bootstrap.php';$u=require_login();$projects=db()->query("SELECT p.*,COALESCE(SUM(d.amount_eur),0) donated FROM projects p LEFT JOIN donations d ON d.project_sic_id=p.sic_id WHERE p.status IN ('ACTIVE','PUBLISHED') GROUP BY p.sic_id ORDER BY p.id DESC")->fetchAll();$pageTitle='Social Impact';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Solidarity Engine</span><h1>La community restituisce valore.</h1><p>Progetti, volontariato e raccolte fondi restano separati dal Rank acquistabile: donare euro non compra status.</p></div></section><div class="course-list"><?php foreach($projects as $p):?><article class="course"><span class="course-cat"><?=h($p['category'])?></span><h3><?=h($p['title'])?></h3><p><?=h($p['description'])?></p><p><b>€ <?=number_format((float)$p['donated'],2,',','.')?></b> raccolti<?= $p['goal_eur']?' su € '.number_format((float)$p['goal_eur'],2,',','.') : ''?></p><a class="btn small" href="project.php?sic=<?=urlencode($p['sic_id'])?>">Apri progetto</a></article><?php endforeach;?></div><?php require '_footer.php';?>